//---------------------------------------------------------------------------//
// Unit test for tools/schar
// Initial implementation generated by GitHub CoPilot (GPT-4.1)
//---------------------------------------------------------------------------//
#include "tools/schar"

#include <gtest/gtest.h>

namespace tools
{
//---------------------------------------------------------------------------//
TEST(Schar, AllSpaces)
{
  EXPECT_TRUE(is_spaces("     "));
}

TEST(Schar, EmptyString)
{
  EXPECT_TRUE(is_spaces(""));
}

TEST(Schar, NoSpaces)
{
  EXPECT_FALSE(is_spaces("abc"));
}

TEST(Schar, MixedSpacesAndChars)
{
  EXPECT_FALSE(is_spaces("  a  "));
  EXPECT_FALSE(is_spaces("a     "));
  EXPECT_FALSE(is_spaces("     a"));
}

TEST(Schar, SingleSpace)
{
  EXPECT_TRUE(is_spaces(" "));
}

TEST(Schar, TabOrOtherWhitespace)
{
  EXPECT_FALSE(is_spaces("\t"));
  EXPECT_FALSE(is_spaces(" \t "));
  EXPECT_FALSE(is_spaces("\n"));
}

TEST(Schar, UnicodeSpaces)
{
  // This is not compatible with C++20! See:
  // - https://stackoverflow.com/questions/56833000/c20-with-u8-char8-t-and-stdstring
  // - https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2019/p1423r2.html
  // EXPECT_FALSE(is_spaces(u8"\u00A0"));  // non-breaking space
  // Use byte sequences for now
  EXPECT_FALSE(is_spaces("\xC2\xA0"));  // non-breaking space
}

//---------------------------------------------------------------------------//
}  // namespace tools
